parameters.jsCode:
// Tâche d'extraction lue depuis la file (mise en série du 17.08.2026) —
// plus aucune constante en dur. mode_desaccord inchangé : consigne dégradée
// du modèle C pour exercer la branche de désaccord (§ 10.4.1).
const runId = $('Ouvrir le run').first().json.run_id;
const MODE_DESACCORD = false; // basculer à true pour provoquer et tracer le désaccord
const d = $input.first().json;
if (!d || !d.doc_id) throw new Error('File de documents vide : aucun document au statut a_traiter dans composite_queue. Inscrire et vérifier un document, puis relancer.');
return [{ json: {
  doc_id: d.doc_id,
  indicator_id: d.indicator_id,
  period: d.period,
  geo: d.geo,
  source_doc: d.source_doc,
  run_id: runId,
  mode_desaccord: MODE_DESACCORD,
  raw_ref: '/data/staging/' + d.indicator_id + '_run' + runId + '.pdf'
} }];

// Construit le prompt d'extraction et le texte du document en une seule charge,
// soumise à l'identique aux trois modèles (sauf consigne dégradée du modèle C en
// mode désaccord). Chaque champ attendu est { valeur, extrait_source } : le
// modèle doit recopier le fragment EXACT du document d'où provient la valeur, ce
// qui rend la validation humaine une comparaison de secondes plutôt qu'une
// relecture (§ 10.4.1, rang 2).
const t = $('Préparer tâche d\'extraction').first().json;
const doc = $input.first().json.text || '';

const schema = {
  periode:                 { valeur: '', extrait_source: '' },
  immatriculations_ue_mois:{ valeur: '', extrait_source: '' },
  part_bev_pct:            { valeur: '', extrait_source: '' }
};

const consigne = `Tu es un extracteur de données. À partir du DOCUMENT ci-dessous (communiqué de presse ACEA sur les immatriculations de voitures neuves), renvoie STRICTEMENT un objet JSON valide conforme au SCHÉMA, sans aucun texte autour, sans balises de code.
Pour CHAQUE champ, renvoie un objet {"valeur": ..., "extrait_source": ...} où extrait_source est le fragment EXACT du document d'où provient la valeur, recopié à l'identique. Si une valeur est absente, écris "ABSENT" dans les deux champs. N'utilise AUCUNE source autre que le document.
Précisions de lecture :
- periode : le mois de référence du communiqué, au format AAAA-MM.
- immatriculations_ue_mois : le total des immatriculations de l'Union européenne pour le MOIS de référence — la ligne « EUROPEAN UNION » du tableau mensuel, colonne du total. PAS le cumul annuel (year-to-date).
- part_bev_pct : la part de marché des voitures 100% électriques à batterie, en pourcentage.
SCHÉMA : ` + JSON.stringify(schema);

// Variante dégradée pour le modèle C : on l'oriente vers le cumul annuel.
const consigne_C = t.mode_desaccord
  ? consigne.replace('PAS le cumul annuel (year-to-date).', 'utilise le CUMUL ANNUEL (year-to-date) cumulé sur l\'année.')
  : consigne;

const enveloppe = (c) => c + '\n\nDOCUMENT :\n' + doc;

return [{ json: {
  ...t,
  prompt_A: enveloppe(consigne),
  prompt_B: enveloppe(consigne),
  prompt_C: enveloppe(consigne_C)
} }];

// Extrait le JSON de la réponse de chaque fournisseur, quelle que soit sa forme.
// Un modèle en échec (clé absente, quota, JSON illisible) devient une extraction
// vide et un incident tracé — il ne fait pas échouer les autres.
function extraireTexte(rep, fournisseur) {
  try {
    if (fournisseur === 'openai') return rep.choices[0].message.content;
    if (fournisseur === 'anthropic') return rep.content[0].text;
    if (fournisseur === 'google') return rep.candidates[0].content.parts[0].text;
  } catch (e) { return null; }
  return null;
}
function parserJson(txt) {
  if (!txt) return null;
  let s = String(txt).trim();
  s = s.replace(/^```(?:json)?/i, '').replace(/```$/,'').trim(); // retire d'éventuelles balises
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i >= 0 && j > i) s = s.slice(i, j + 1);
  try { return JSON.parse(s); } catch (e) { return null; }
}

const sources = [
  { modele: 'gpt-4o',            fournisseur: 'openai',    node: 'Modèle A (OpenAI)' },
  { modele: 'claude-opus-4-8',   fournisseur: 'anthropic', node: 'Modèle B (Anthropic)' },
  { modele: 'gemini-pro-latest', fournisseur: 'google',    node: 'Modèle C (Google)' }
];

const extractions = [];
const incidents = [];
for (const s of sources) {
  let rep;
  try { rep = $(s.node).first().json; } catch (e) { rep = null; }
  const err = rep && rep.error ? JSON.stringify(rep.error).slice(0,200) : null;
  const parsed = parserJson(extraireTexte(rep, s.fournisseur));
  if (err) incidents.push(s.modele + ' : appel en échec (' + err + ')');
  else if (!parsed) incidents.push(s.modele + ' : réponse non parsable en JSON');
  extractions.push({ modele: s.modele, extraction: parsed || {} });
}

const t = $('Consolider le contexte').first().json;
return [{ json: {
  indicator_id: t.indicator_id, run_id: t.run_id, period: t.period, geo: t.geo,
  source_doc: t.source_doc, raw_ref: t.raw_ref, mode_desaccord: t.mode_desaccord,
  extractions, incidents
} }];

// Consensus champ par champ sur la VALEUR. Une valeur unanime mais sans extrait
// vérifiable ne compte pas comme consensus : l'accord sur une affirmation
// invérifiable n'est pas une preuve (§ 6.3). Le consensus est une heuristique de
// priorisation, jamais une vérité — la hiérarchie reste vérité terrain, puis
// consensus, puis validation humaine.
const j = $input.first().json;
const parsed = j.extractions.map(e => e.extraction || {});
const champs = ['periode', 'immatriculations_ue_mois', 'part_bev_pct'];

const norm = (v) => String(v ?? '').trim().replace(/\s|,/g, '').toLowerCase();
let accord = 0;
const detail = {};
for (const f of champs) {
  const vals = parsed.map(p => norm(p[f]?.valeur ?? p[f]));
  const extraits = parsed.map(p => String(p[f]?.extrait_source ?? '').trim());
  const unanime = vals.every(v => v === vals[0] && v !== '' && v !== 'absent');
  const tous_sources = extraits.every(e => e !== '' && e.toLowerCase() !== 'absent') || vals[0] === 'absent';
  detail[f] = { valeurs: parsed.map(p => p[f]?.valeur ?? p[f] ?? null), extraits_source: extraits, unanime, tous_sources };
  if (unanime && tous_sources) accord++;
}
const consensus_score = champs.length ? accord / champs.length : 0;
let unanimous = consensus_score === 1;

// Garde de concordance de période (17.08.2026) : la période extraite du
// DOCUMENT doit être celle que la file ANNONCE. Un communiqué mal apparié
// (décalage de nommage ACEA, cumul lu à la place du mensuel) écrirait une
// valeur juste sous un mois faux — indétectable ensuite. En cas d'écart,
// validation humaine forcée, jamais d'écriture directe.
const periodeExtraite = norm(parsed[0]?.periode?.valeur ?? parsed[0]?.periode);
if (unanimous && periodeExtraite && periodeExtraite !== norm(j.period)) {
  unanimous = false;
  j.incidents = (j.incidents ?? []).concat('période extraite (' + periodeExtraite + ') != période attendue (' + j.period + ') — validation humaine forcée');
}

// Valeur pivot proposée : immatriculations mensuelles UE (numérique), si unanime.
let valeur_pivot = null;
if (detail.immatriculations_ue_mois.unanime) {
  const brut = String(parsed[0].immatriculations_ue_mois?.valeur ?? '').replace(/[^0-9]/g, '');
  if (brut) valeur_pivot = Number(brut);
}

return [{ json: { ...j, consensus_score, unanimous, valeur_pivot, detail } }];

